import React, {useEffect, useId, useRef, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowUp, ArrowUpRight, ArrowRight, Check, CheckCheck, ChevronDown, ChevronRight, ChevronsLeft, CircleHelp, CirclePause, Code2, Command, Copy, FileText, Folder, GitBranch, Globe, Home, Layers3, LayoutGrid, Link, Loader2, Menu, MessageSquare, Mic, Monitor, Moon, MoreHorizontal, Paperclip, Plus, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Square, Sun, Terminal, X, ZoomIn, ZoomOut, Maximize2, Clock3, CheckCircle2, AlertCircle, Palette, Plug, Wrench, LockKeyhole, Activity, Keyboard, Download, Send, RotateCcw} from 'lucide-react';
